import { Component, signal } from '@angular/core';
import { CurrencyPipe } from '@angular/common';

@Component({
  selector: 'app-cart-summary',
  imports: [CurrencyPipe],
  template: `
    <input #note (input)="giftNote.set(note.value)" />
    <p>Total: {{ total | currency: 'EGP' }}</p>
  `,
})
export class CartSummary {
  readonly lines = signal<CartLine[]>([]);
  readonly giftNote = signal('');

  // No parentheses in the template, yet it runs on every check
  get total(): number {
    return this.lines().reduce((sum, l) => sum + lineTotal(l), 0);
  }
}

import { Component, computed, signal } from '@angular/core';
import { CurrencyPipe } from '@angular/common';

@Component({
  selector: 'app-cart-summary',
  imports: [CurrencyPipe],
  template: `
    <input #note (input)="giftNote.set(note.value)" />
    <p>Total: {{ total() | currency: 'EGP' }}</p>
  `,
})
export class CartSummary {
  readonly lines = signal<CartLine[]>([]);
  readonly giftNote = signal('');

  // Runs on first read, then again only when lines() changes
  readonly total = computed(() =>
    this.lines().reduce((sum, l) => sum + lineTotal(l), 0),
  );
}

